INSERT INTO trash_item_translation (
  id, item_id, language, caption, disposal_instructions, object_material, sub_classifications, price, nearby_recycling_places, created_at
) VALUES
  ('dd000000-0000-4000-8000-000000000001', 'cc000000-0000-4000-8000-000000000001', 'pt', 'Garrafa de água mineral (PET #1, 500 ml)', '1. Esvazie o líquido restante e passe uma água rápida. 2. Amasse no sentido vertical para reduzir o volume na coleta. 3. Rosqueie a tampa novamente e deposite no cesto de plásticos secos.', 'Polietileno Tereftalato (PET #1) com tampa PEAD #2', 'Processo: Extrusão mecânica bottle-to-bottle · Norma: Resina #1 (PET) · Restrição: Esvaziar líquidos e remover lacres de PVC', 'R$ 4,50 / kg (~R$ 0,15 / garrafa)', 'Ecoponto Pinheiros (0,6 km) · Cooperativa Vila Mariana (2,1 km)', now() - interval '11 days'),
  ('dd000000-0000-4000-8000-000000000002', 'cc000000-0000-4000-8000-000000000001', 'es', 'Botella de agua mineral (PET #1, 500 ml)', '1. Vacíe el líquido restante y enjuague brevemente. 2. Aplaste a lo largo para ahorrar espacio. 3. Vuelva a colocar la tapa y deposítela en el contenedor de plásticos secos.', 'Tereftalato de polietileno (PET #1) con tapa PEAD #2', 'Proceso: Extrusión mecánica botella a botella · Norma: Resina #1 (PET) · Restricción: Vaciar líquidos y retirar etiquetas de PVC', 'US$ 0,85 / kg (~US$ 0,03 / botella)', 'Ecoponto Pinheiros (0,6 km) · Cooperativa Vila Mariana (2,1 km)', now() - interval '11 days'),
  ('dd000000-0000-4000-8000-000000000003', 'cc000000-0000-4000-8000-000000000001', 'ru', 'Бутылка из-под минеральной воды (ПЭТ #1, 500 мл)', '1. Вылейте остатки жидкости и слегка ополосните. 2. Сожмите бутылку вдоль для экономии места. 3. Закрутите крышку и отправьте в контейнер для сухого пластика.', 'Полиэтилентерефталат (ПЭТ #1) с крышкой ПНД #2', 'Процесс: Механическая экструзия ПЭТ-флексы · Стандарт: Код смолы #1 (PET) · Ограничение: Слить жидкость и снять ПВХ-этикетку', '0,85 $ / кг (~0,03 $ за бутылку)', 'Экопункт Пиньейрус (0,6 км) · Кооператив Вила-Мариана (2,1 км)', now() - interval '11 days'),
  ('dd000000-0000-4000-8000-000000000004', 'cc000000-0000-4000-8000-000000000001', 'he', 'בקבוק מים מינרליים (PET #1, 500 מ״ל)', '1. רוקנו שאריות נוזל ושטפו קלות. 2. מעכו לאורך לחיסכון בנפח. 3. הבריגו חזרה את הפקק והשליכו לפח הפלסטיק היבש.', 'פוליאתילן טרפתאלט (PET #1) עם פקק HDPE #2', 'תהליך: גריסה ושיחול מכני לבקבוקים חדשים · תקן: קוד שרף #1 (PET) · הגבלה: לרוקן נוזלים ולהסיר שרוולי PVC', '0.85 $ לק״ג (~0.03 $ לבקבוק)', 'אקופונטו פיניירוס (0.6 ק״מ) · קואופרטיב וילה מריאנה (2.1 ק״מ)', now() - interval '11 days'),
  ('dd000000-0000-4000-8000-000000000005', 'cc000000-0000-4000-8000-000000000001', 'kk', 'Минералды су бөтелкесі (ПЭТ #1, 500 мл)', '1. Қалған сұйықтықты төгіп, шайып жіберіңіз. 2. Көлемін азайту үшін ұзынынан сығымдаңыз. 3. Қақпағын жауып, құрғақ пластик контейнеріне салыңыз.', 'Полиэтилентерефталат (ПЭТ #1) және ПНД #2 қақпағы', 'Үдеріс: ПЭТ түйіршіктерін механикалық экструзиялау · Стандарт: Шайыр коды #1 (PET) · Шектеу: Сұйықтықты толық төгу', '0,85 $ / кг (~0,03 $ / бөтелке)', 'Пиньейрус экобекеті (0,6 км) · Вила-Мариана кооперативі (2,1 км)', now() - interval '11 days'),
  ('dd000000-0000-4000-8000-000000000006', 'cc000000-0000-4000-8000-000000000002', 'pt', 'Lata de bebida (Alumínio #41, 350 ml)', '1. Escorra o restante da bebida e enxágue rapidamente. 2. Mantenha o anel preso à lata. 3. Amasse a lata para reduzir o volume e deposite no coletor de metais.', 'Liga de alumínio laminado 3004/5182 (ALU #41)', 'Processo: Refundição em ciclo fechado (economia de 95% de energia) · Norma: CEN #41 ALU · Restrição: Sem terra, areia ou bitucas', 'R$ 7,80 / kg (~R$ 0,10 / lata)', 'Cooperativa Vila Mariana (1,4 km) · Ecoponto Pinheiros (1,9 km)', now() - interval '10 days'),
  ('dd000000-0000-4000-8000-000000000007', 'cc000000-0000-4000-8000-000000000002', 'es', 'Lata de bebida (Aluminio #41, 350 ml)', '1. Escurra el líquido restante y enjuague brevemente. 2. Mantenga la anilla unida a la lata. 3. Aplaste la lata y deposítela en el contenedor de metales.', 'Aleación de aluminio forjado 3004/5182 (ALU #41)', 'Proceso: Fundición de ciclo cerrado (95% ahorro energético) · Norma: CEN #41 ALU · Restricción: Libre de tierra o ceniza', 'US$ 1,45 / kg (~US$ 0,02 / lata)', 'Cooperativa Vila Mariana (1,4 km) · Ecoponto Pinheiros (1,9 km)', now() - interval '10 days'),
  ('dd000000-0000-4000-8000-000000000008', 'cc000000-0000-4000-8000-000000000002', 'ru', 'Банка из-под напитка (Алюминий #41, 350 мл)', '1. Слейте остатки напитка и ополосните банку. 2. Оставьте ключ-кольцо на крышке. 3. Сожмите банку и поместите в контейнер для металла.', 'Деформируемый алюминиевый сплав 3004/5182 (ALU #41)', 'Процесс: Переплавка замкнутого цикла (экономия 95% энергии) · Стандарт: CEN #41 ALU · Ограничение: Без грунта и пепла', '1,45 $ / кг (~0,02 $ за банку)', 'Кооператив Вила-Мариана (1,4 км) · Экопункт Пиньейрус (1,9 км)', now() - interval '10 days'),
  ('dd000000-0000-4000-8000-000000000009', 'cc000000-0000-4000-8000-000000000002', 'he', 'פחית משקה (אלומיניום #41, 350 מ״ל)', '1. רוקנו שאריות משקה ושטפו קלות. 2. השאירו את לשונית הפתיחה מחוברת. 3. מעכו את הפחית והשליכו לפח המתכות.', 'סגסוגת אלומיניום 3004/5182 (ALU #41)', 'תהליך: התכה במעגל סגור (חיסכון של 95% באנרגיה) · תקן: CEN #41 ALU · הגבלה: ללא עפר או בדלי סיגריות', '1.45 $ לק״ג (~0.02 $ לפחית)', 'קואופרטיב וילה מריאנה (1.4 ק״מ) · אקופונטו פיניירוס (1.9 ק״מ)', now() - interval '10 days'),
  ('dd000000-0000-4000-8000-000000000010', 'cc000000-0000-4000-8000-000000000002', 'kk', 'Сусын қалбыры (Алюминий #41, 350 мл)', '1. Қалған сусынды төгіп, шайып жіберіңіз. 2. Ашқыш сақинасын орнында қалдырыңыз. 3. Қалбырды сығымдап, металл контейнеріне салыңыз.', 'Соғылған алюминий қорытпасы 3004/5182 (ALU #41)', 'Үдеріс: Тұйық циклді қайта балқыту (95% энергия үнемдеу) · Стандарт: CEN #41 ALU · Шектеу: Топырақ пен күлсіз', '1,45 $ / кг (~0,02 $ / қалбыр)', 'Вила-Мариана кооперативі (1,4 км) · Пиньейрус экобекеті (1,9 км)', now() - interval '10 days'),
  ('dd000000-0000-4000-8000-000000000011', 'cc000000-0000-4000-8000-000000000003', 'pt', 'Caixa de papelão ondulado e fardo kraft (PAP #20)', '1. Retire fitas adesivas plásticas, etiquetas de envio e grampos metálicos. 2. Desmonte e dobre as abas a plano para manter as fibras secas. 3. Entregue na coleta seletiva de papéis secos.', 'Papelão ondulado kraft de fibra longa não branqueada (PAP #20)', 'Processo: Hidrapulper e repolpagem de capa/miolo (5 a 7 ciclos) · Norma: CEN #20 PAP · Restrição: Manter seco, sem gordura ou parafina', 'R$ 0,95 / kg de fibra (~R$ 25,00 reuso da caixa)', 'Cooperativa Vila Mariana (0,5 km) · Ecoponto Pinheiros (2,8 km)', now() - interval '9 days'),
  ('dd000000-0000-4000-8000-000000000012', 'cc000000-0000-4000-8000-000000000003', 'es', 'Caja de cartón corrugado y fardo kraft (PAP #20)', '1. Retire cintas adhesivas plásticas, etiquetas y grapas metálicas. 2. Pliegue la caja en plano para mantener las fibras secas. 3. Deposítela en el contenedor de papel y cartón.', 'Cartón corrugado kraft de fibra larga sin blanquear (PAP #20)', 'Proceso: Hidropulper y repulpado de fibra (5 a 7 ciclos) · Norma: CEN #20 PAP · Restricción: Mantener seco y sin grasa ni parafina', 'US$ 0,18 / kg fibra (~US$ 5,00 reúso)', 'Cooperativa Vila Mariana (0,5 km) · Ecoponto Pinheiros (2,8 km)', now() - interval '9 days'),
  ('dd000000-0000-4000-8000-000000000013', 'cc000000-0000-4000-8000-000000000003', 'ru', 'Коробка из гофрокартона и крафт-связка (PAP #20)', '1. Удалите пластиковый скотч, наклейки и металлические скобы. 2. Сложите коробку в плоский вид, чтобы волокно оставалось сухим. 3. Сдайте в контейнер для сухой макулатуры.', 'Небеленый длинноволокнистый крафт-гофрокартон (PAP #20)', 'Процесс: Гидроразбивка и вторичное формование картона (5–7 циклов) · Стандарт: CEN #20 PAP · Ограничение: Без жира, влаги и парафина', '0,18 $ / кг волокна (~5,00 $ повторное использование)', 'Кооператив Вила-Мариана (0,5 км) · Экопункт Пиньейрус (2,8 км)', now() - interval '9 days'),
  ('dd000000-0000-4000-8000-000000000014', 'cc000000-0000-4000-8000-000000000003', 'he', 'ארגז קרטון גלי וצרור נייר קראפט (PAP #20)', '1. הסירו סרטי הדבקה מפלסטיק, מדבקות משלוח וסיכות מתכת. 2. שטחו את הארגז כדי לשמור על הסיבים יבשים. 3. השליכו למכל איסוף נייר וקרטון.', 'קרטון גלי קראפט מסיבים ארוכים לא מולבנים (PAP #20)', 'תהליך: הפיכה לעיסה וייצור קרטון מחודש (5–7 מחזורי סיב) · תקן: CEN #20 PAP · הגבלה: לשמור יבש וללא שומן או שעווה', '0.18 $ לק״ג סיב (~5.00 $ בשימוש חוזר)', 'קואופרטיב וילה מריאנה (0.5 ק״מ) · אקופונטו פיניירוס (2.8 ק״מ)', now() - interval '9 days'),
  ('dd000000-0000-4000-8000-000000000015', 'cc000000-0000-4000-8000-000000000003', 'kk', 'Гофрокартон қорабы және крафт бумасы (PAP #20)', '1. Пластик скотчты, жапсырмаларды және металл қапсырмаларды алып тастаңыз. 2. Қорапты құрғақ әрі ықшам ұстау үшін жазып бүктеңіз. 3. Қағаз бен картон контейнеріне салыңыз.', 'Ағартылмаған ұзын талшықты крафт-гофрокартон (PAP #20)', 'Үдеріс: Гидропульпалау және қайта картон басу (5–7 цикл) · Стандарт: CEN #20 PAP · Шектеу: Май мен ылғал тигізбеу', '0,18 $ / кг талшық (~5,00 $ қайта қолдану)', 'Вила-Мариана кооперативі (0,5 км) · Пиньейрус экобекеті (2,8 км)', now() - interval '9 days'),
  ('dd000000-0000-4000-8000-000000000016', 'cc000000-0000-4000-8000-000000000004', 'pt', 'Garrafa de vidro transparente (GL #70, 355 ml)', '1. Enxágue a garrafa para remover resíduos da bebida. 2. Retire a tampa metálica e destine-a aos metais. 3. Deposite a garrafa inteira no coletor de vidros.', 'Vidro sodo-cálcico incolor para envase (GL #70)', 'Processo: Refundição de caco em forno (100% refundível infinitamente) · Norma: CEN #70 GL · Restrição: Não misturar com cerâmica, pirex ou espelhos', 'R$ 0,48 / kg de caco limpo', 'Cooperativa Vila Mariana (1,1 km) · Ecoponto Pinheiros (0,8 km)', now() - interval '8 days'),
  ('dd000000-0000-4000-8000-000000000017', 'cc000000-0000-4000-8000-000000000004', 'es', 'Botella de vidrio transparente (GL #70, 355 ml)', '1. Enjuague la botella para eliminar residuos de bebida. 2. Retire la tapa metálica y sepárela con los metales. 3. Deposite la botella íntegra en el contenedor de vidrio.', 'Vidrio sodocálcico incoloro de envase (GL #70)', 'Proceso: Refundición de calcín en horno (100% reciclable infinitamente) · Norma: CEN #70 GL · Restricción: No mezclar con cerámica, pírex ni espejos', 'US$ 0,09 / kg de calcín', 'Cooperativa Vila Mariana (1,1 km) · Ecoponto Pinheiros (0,8 km)', now() - interval '8 days'),
  ('dd000000-0000-4000-8000-000000000018', 'cc000000-0000-4000-8000-000000000004', 'ru', 'Прозрачная стеклянная бутылка (GL #70, 355 мл)', '1. Сполосните бутылку от остатков напитка. 2. Снимите металлическую крышку и сдайте её с металлом. 3. Поместите целую бутылку в контейнер для стекла.', 'Бесцветное натрий-кальций-силикатное тарное стекло (GL #70)', 'Процесс: Переплавка стеклобоя в печи (100% бесконечный цикл) · Стандарт: CEN #70 GL · Ограничение: Не смешивать с керамикой, жаропрочным стеклом и зеркалами', '0,09 $ / кг стеклобоя', 'Кооператив Вила-Мариана (1,1 км) · Экопункт Пиньейрус (0,8 км)', now() - interval '8 days'),
  ('dd000000-0000-4000-8000-000000000019', 'cc000000-0000-4000-8000-000000000004', 'he', 'בקבוק זכוכית שקוף (GL #70, 355 מ״ל)', '1. שטפו את הבקבוק משאריות משקה. 2. הסירו את פקק המתכת והפרידו למתכות. 3. השליכו את הבקבוק השלם למכל איסוף הזכוכית.', 'זכוכית סודה-ליים שקופה למזון ומשקאות (GL #70)', 'תהליך: התכת גרוסת זכוכית בתנור (ניתן להתכה חוזרת אינסופית) · תקן: CEN #70 GL · הגבלה: אין לערבב עם קרמיקה, פיירקס או מראות', '0.09 $ לק״ג זכוכית', 'קואופרטיב וילה מריאנה (1.1 ק״מ) · אקופונטו פיניירוס (0.8 ק״מ)', now() - interval '8 days'),
  ('dd000000-0000-4000-8000-000000000020', 'cc000000-0000-4000-8000-000000000004', 'kk', 'Мөлдір шыны бөтелке (GL #70, 355 мл)', '1. Бөтелкені сусын қалдықтарынан шайыңыз. 2. Металл қақпағын шешіп, металдарға бөлек салыңыз. 3. Бүтін бөтелкені шыны контейнеріне салыңыз.', 'Түссіз натрий-кальций-силикатты ыдыс шынысы (GL #70)', 'Үдеріс: Шыны сынықтарын пеште қайта балқыту (шексіз цикл) · Стандарт: CEN #70 GL · Шектеу: Керамика, пирекс және айнамен араластырмау', '0,09 $ / кг шыны сынығы', 'Вила-Мариана кооперативі (1,1 км) · Пиньейрус экобекеті (0,8 км)', now() - interval '8 days'),
  ('dd000000-0000-4000-8000-000000000021', 'cc000000-0000-4000-8000-000000000005', 'pt', 'Cascas de banana e borra de café com filtro de papel', '1. Retire eventuais selos adesivos das cascas de fruta. 2. Intercale 1 parte de restos úmidos com 2 partes de serragem ou folhas secas no minhocário. 3. Ou entregue em pátio comunitário de compostagem.', 'Cascas ricas em potássio e borra nitrogenada com celulose (C:N ~20:1)', 'Processo: Vermicompostagem ou leira termofílica · Ciclo: 45 a 60 dias · Restrição: Remover adesivos plásticos de frutas e sachês sintéticos', 'Rende ~0,4 kg de húmus / kg', 'Horta Comunitária Butantã (0,4 km) · Pátio de Compostagem Pinheiros (1,7 km)', now() - interval '7 days'),
  ('dd000000-0000-4000-8000-000000000022', 'cc000000-0000-4000-8000-000000000005', 'es', 'Cáscaras de plátano y posos de café con filtro', '1. Retire cualquier etiqueta adhesiva de las frutas. 2. Intercale 1 parte de restos húmedos con 2 partes de hojas secas o aserrín en la lombricompostera. 3. O entréguelo en un patio de compostaje barrial.', 'Cáscaras ricas en potasio y posos nitrogenados con celulosa (C:N ~20:1)', 'Proceso: Lombricompostaje o pila termofílica · Ciclo: 45 a 60 días · Restricción: Retirar pegatinas plásticas de fruta y bolsitas sintéticas', 'Rinde ~0,4 kg de humus / kg', 'Huerta Comunitaria Butantã (0,4 km) · Patio de Compostaje Pinheiros (1,7 km)', now() - interval '7 days'),
  ('dd000000-0000-4000-8000-000000000023', 'cc000000-0000-4000-8000-000000000005', 'ru', 'Банановая кожура и кофейная гуща с бумажным фильтром', '1. Снимите пластиковые наклейки с кожуры фруктов. 2. Чередуйте 1 часть влажных остатков с 2 частями сухих листьев или опилок в вермикомпостере. 3. Либо сдайте на районную площадку компостирования.', 'Богатая калием кожура и азотистая кофейная гуща с целлюлозой (C:N ~20:1)', 'Процесс: Вермикомпостирование или термофильный бурт · Цикл: 45–60 дней · Ограничение: Удалить пластиковые стикеры и синтетические чайные пакетики', 'Выход ~0,4 кг гумуса на 1 кг', 'Общественный сад Бутантан (0,4 км) · Площадка компостирования Пиньейрус (1,7 км)', now() - interval '7 days'),
  ('dd000000-0000-4000-8000-000000000024', 'cc000000-0000-4000-8000-000000000005', 'he', 'קליפות בננה ושאריות קפה טחון עם פילטר נייר', '1. הסירו מדבקות פלסטיק מקליפות הפרי. 2. שלבו חלק אחד של שאריות לחות עם 2 חלקים של עלים יבשים או נסורת בקומפוסטר תולעים. 3. או מסרו לחצר קומפוסט קהילתית.', 'קליפות עשירות באשלגן ובוץ קפה חנקני עם תאית (יחס פחמן-חנקן ~20:1)', 'תהליך: קומפוסט תולעים או ערימה תרמופילית · מחזור: 45–60 יום · הגבלה: להסיר מדבקות פרי מפלסטיק ושקיקים סינתטיים', 'מפיק ~0.4 ק״ג הומוס לק״ג', 'גינה קהילתית בוטנטן (0.4 ק״מ) · חצר קומפוסט פיניירוס (1.7 ק״מ)', now() - interval '7 days'),
  ('dd000000-0000-4000-8000-000000000025', 'cc000000-0000-4000-8000-000000000005', 'kk', 'Банан қабығы мен қағаз сүзгідегі кофе қоюы', '1. Жеміс қабығындағы пластик жапсырмаларды алып тастаңыз. 2. 1 бөлік ылғал қалдықты 2 бөлік құрғақ жапырақ немесе үгіндімен қабаттастырыңыз. 3. Немесе аудандық компосттау алаңына тапсырыңыз.', 'Калийге бай қабықтар және целлюлозалы азотты кофе қоюы (C:N ~20:1)', 'Үдеріс: Вермикомпосттау немесе термофильді қорда · Цикл: 45–60 күн · Шектеу: Пластик жапсырмалар мен синтетикалық қалташаларды қоспау', '1 кг-нан ~0,4 кг гумус алынады', 'Бутантан қоғамдық бағы (0,4 км) · Пиньейрус компост алаңы (1,7 км)', now() - interval '7 days'),
  ('dd000000-0000-4000-8000-000000000026', 'cc000000-0000-4000-8000-000000000006', 'pt', 'Bateria de íons de lítio e módulo de smartphone (58 Wh)', '1. Isole os polos metálicos com fita isolante antes do transporte. 2. Não perfure, dobre nem exponha a bateria à umidade. 3. Entregue em coletor certificado de logística reversa de baterias.', 'Células LiCoO2 em bolsa com circuito BMS de cobre e carcaça ABS', 'Processo: Recuperação hidrometalúrgica de cobalto, lítio e cobre · Norma: ABNT NBR 16156 / REEE · Restrição: Risco de incêndio se compactada no caminhão comum', 'R$ 17,50 / kg em minerais críticos', 'Ponto Verde Paulista (0,3 km) · Ecoponto Pinheiros (1,9 km)', now() - interval '6 days'),
  ('dd000000-0000-4000-8000-000000000027', 'cc000000-0000-4000-8000-000000000006', 'es', 'Batería de iones de litio y módulo de smartphone (58 Wh)', '1. Aísle los bornes metálicos con cinta no conductora. 2. No perfore, aplaste ni exponga la batería a la humedad. 3. Entréguela en un punto autorizado de recogida RAEE.', 'Celdas LiCoO2 tipo bolsa con circuito BMS de cobre y carcasa ABS', 'Proceso: Recuperación hidrometalúrgica de cobalto, litio y cobre · Norma: RAEE Categoría 4/5 · Restricción: Riesgo de incendio si se compacta en basura común', 'US$ 3,20 / kg minerales críticos', 'Ponto Verde Paulista (0,3 km) · Ecoponto Pinheiros (1,9 km)', now() - interval '6 days'),
  ('dd000000-0000-4000-8000-000000000028', 'cc000000-0000-4000-8000-000000000006', 'ru', 'Литий-ионный аккумулятор и модуль смартфона (58 Вт·ч)', '1. Заизолируйте металлические контакты изолентой перед сдачей. 2. Не прокалывайте, не сгибайте и берегите от влаги. 3. Сдайте в сертифицированный пункт приема батарей и электроники.', 'Ячейки LiCoO2, медная плата BMS и корпус из АБС-пластика', 'Процесс: Гидрометаллургическое извлечение кобальта, лития и меди · Стандарт: WEEE Категория 4/5 · Ограничение: Пожароопасно при прессовании в бытовом мусоре', '3,20 $ / кг критических металлов', 'Понту-Верди Паулиста (0,3 км) · Экопункт Пиньейрус (1,9 км)', now() - interval '6 days'),
  ('dd000000-0000-4000-8000-000000000029', 'cc000000-0000-4000-8000-000000000006', 'he', 'סוללת ליתיום-יון ומודול סמארטפון (58 Wh)', '1. בודדו את מגעי המתכת בסרט בידוד לפני המסירה. 2. אין לנקב, למעוך או לחשוף ללחות. 3. מסרו בנקודת איסוף מוסמכת לפסולת אלקטרונית וסוללות.', 'תאי LiCoO2, מעגל בקרה מנחושת ומארז ABS', 'תהליך: מיצוי הידרו-מטאלורגי של קובלט, ליתיום ונחושת · תקן: WEEE קטגוריה 4/5 · הגבלה: סכנת התלקחות בדחסני אשפה ביתית', '3.20 $ לק״ג מתכות קריטיות', 'פונטו ורדה פאוליסטה (0.3 ק״מ) · אקופונטו פיניירוס (1.9 ק״מ)', now() - interval '6 days'),
  ('dd000000-0000-4000-8000-000000000030', 'cc000000-0000-4000-8000-000000000006', 'kk', 'Литий-ионды аккумулятор және смартфон модулі (58 Вт·сағ)', '1. Металл түйіспелерін оқшаулағыш таспамен жабыңыз. 2. Теспеңіз, майыстырмаңыз және ылғалдан сақтаңыз. 3. Сертификатталған электронды қалдықтарды қабылдау бекетіне тапсырыңыз.', 'LiCoO2 ұяшықтары, мыс BMS тақтасы және ABS корпусы', 'Үдеріс: Кобальт, литий және мысты гидрометаллургиялық бөлу · Стандарт: WEEE 4/5 санаты · Шектеу: Тұрмыстық қоқыста нығыздалса өрт қаупі бар', '3,20 $ / кг маңызды металдар', 'Понту-Верди Паулиста (0,3 км) · Пиньейрус экобекеті (1,9 км)', now() - interval '6 days'),
  ('dd000000-0000-4000-8000-000000000031', 'cc000000-0000-4000-8000-000000000007', 'pt', 'Caneca de grés esmaltado rachada e bocal de porcelana', '1. Nunca coloque cerâmica no cesto de vidros — ela não funde no forno vidreiro. 2. Embale os cacos cortantes em papelão grosso e identifique o pacote. 3. Entregue na baia de inertes de um ecoponto.', 'Cerâmica de grés aluminossilicato vitrificado e porcelana isolante', 'Processo: Britagem para agregado mineral de sub-base · Norma: ABNT NBR 10004 Classe II-B (Inerte) · Restrição: Contamina fornadas inteiras de vidro se misturada', 'Reaproveitamento como agregado mineral', 'Ecoponto Pinheiros — Baia de Inertes (1,2 km)', now() - interval '5 days'),
  ('dd000000-0000-4000-8000-000000000032', 'cc000000-0000-4000-8000-000000000007', 'es', 'Taza de gres esmaltado agrietada y portalámparas de porcelana', '1. No deposite cerámica en el contenedor de vidrio. 2. Envuelva los fragmentos cortantes en cartón grueso y rotule el paquete. 3. Llévelo a una bahía de áridos inertes en un ecopunto.', 'Gres aluminosilicato vitrificado y porcelana aislante de alta temperatura', 'Proceso: Trituración para árido mineral de subbase · Norma: Residuo Mineral Inerte Clase II-B · Restricción: Contamina los hornos de vidrio sodocálcico', 'Recuperación como árido mineral inerte', 'Ecoponto Pinheiros — Bahía de Inertes (1,2 km)', now() - interval '5 days'),
  ('dd000000-0000-4000-8000-000000000033', 'cc000000-0000-4000-8000-000000000007', 'ru', 'Треснутая глазурованная кружка и фарфоровый патрон', '1. Не выбрасывайте керамику в контейнер для стекла. 2. Заверните острые осколки в плотный картон и подпишите сверток. 3. Сдайте в отсек инертных минеральных отходов экопункта.', 'Спеченная алюмосиликатная каменная керамика и электротехнический фарфор', 'Процесс: Дробление в инертный щебень для дорожной отсыпки · Стандарт: Инертный минеральный класс II-B · Ограничение: Загрязняет плавку тарного стекла', 'Переработка в инертный минеральный заполнитель', 'Экопункт Пиньейрус — Отсек инертных материалов (1,2 км)', now() - interval '5 days'),
  ('dd000000-0000-4000-8000-000000000034', 'cc000000-0000-4000-8000-000000000007', 'he', 'ספל קרמיקה מזוגג סדוק ובית נורה מפורצלן', '1. אל תשליכו קרמיקה למכל הזכוכית — נקודת ההתכה שלה שונה. 2. עטפו שברים חדים בקרטון עבה וסמנו בבירור. 3. מסרו במפרץ פסולת המינרלים האינרטית באקופונטו.', 'קרמיקת אבן אלומינו-סיליקטית מזוגגת ופורצלן מבודד חום', 'תהליך: גריסה למילוי מינרלי אינרטי לתשתיות · תקן: מינרל אינרטי סוג II-B · הגבלה: מזהם תנורי התכת זכוכית', 'השבה כמצע מינרלי אינרטי', 'אקופונטו פיניירוס — מפרץ חומרים אינרטיים (1.2 ק״מ)', now() - interval '5 days'),
  ('dd000000-0000-4000-8000-000000000035', 'cc000000-0000-4000-8000-000000000007', 'kk', 'Шытынаған глазурьленген саптыаяқ пен фарфор патрон', '1. Керамиканы шыны контейнеріне салмаңыз. 2. Өткір сынықтарды қалың картонға орап, сыртына белгі қойыңыз. 3. Экобекеттің инертті минералдар бөліміне тапсырыңыз.', 'Күйдірілген алюмосиликатты тас керамика және оқшаулағыш фарфор', 'Үдеріс: Жол негізіне арналған инертті қиыршыққа ұсақтау · Стандарт: II-B класты инертті минерал · Шектеу: Шыны балқыту пешін бүлдіреді', 'Инертті минералды толтырғыш ретінде өңдеу', 'Пиньейрус экобекеті — Инертті материалдар бөлімі (1,2 км)', now() - interval '5 days'),
  ('dd000000-0000-4000-8000-000000000036', 'cc000000-0000-4000-8000-000000000008', 'pt', 'Pote termoformado de laticínios (PP #5, 170 g)', '1. Raspe e enxágue qualquer resto de iogurte ou manteiga. 2. Destaque totalmente o lacre metalizado da borda. 3. Empilhe o pote seco e deposite no cesto de plásticos.', 'Homopolímero de Polipropileno Isotático (PP #5)', 'Processo: Moagem e injeção de polipropileno secundário · Norma: Resina #5 (PP) · Restrição: Destacar o selo de alumínio antes de descartar', 'R$ 2,20 / kg', 'Ecoponto Pinheiros (0,6 km) · Cooperativa Vila Mariana (2,1 km)', now() - interval '5 days'),
  ('dd000000-0000-4000-8000-000000000037', 'cc000000-0000-4000-8000-000000000008', 'es', 'Envase termoformado de lácteos (PP #5, 170 g)', '1. Enjuague cualquier resto de yogur o mantequilla. 2. Despegue por completo el sello de aluminio del borde. 3. Apile el envase seco y deposítelo en el contenedor de plásticos.', 'Homopolímero de polipropileno isotáctico (PP #5)', 'Proceso: Molienda e inyección de polipropileno secundario · Norma: Resina #5 (PP) · Restricción: Retirar la tapa laminada de aluminio', 'US$ 0,42 / kg', 'Ecoponto Pinheiros (0,6 km) · Cooperativa Vila Mariana (2,1 km)', now() - interval '5 days'),
  ('dd000000-0000-4000-8000-000000000038', 'cc000000-0000-4000-8000-000000000008', 'ru', 'Термоформованный стаканчик из-под молочных продуктов (PP #5, 170 г)', '1. Сполосните стаканчик от остатков йогурта или масла. 2. Полностью снимите фольгированную мембрану с ободка. 3. Сложите сухую тару и отправьте в контейнер для пластика.', 'Изотактический гомополимер полипропилена (ПП #5)', 'Процесс: Дробление и литье вторичного полипропилена · Стандарт: Код смолы #5 (PP) · Ограничение: Отделить алюминиевую крышку-фольгу', '0,42 $ / кг', 'Экопункт Пиньейрус (0,6 км) · Кооператив Вила-Мариана (2,1 км)', now() - interval '5 days'),
  ('dd000000-0000-4000-8000-000000000039', 'cc000000-0000-4000-8000-000000000008', 'he', 'גביע מוצרי חלב מעוצב בחום (PP #5, 170 גרם)', '1. שטפו שאריות יוגורט או חמאה מהגביע. 2. קלפו לחלוטין את מכסה הרדיד המתכתי מהשפה. 3. ערמו את הגביעים היבשים והשליכו לפח הפלסטיק.', 'פוליפרופילן איזוטקטי הומופולימרי (PP #5)', 'תהליך: גריסה והזרקת פוליפרופילן ממוחזר · תקן: קוד שרף #5 (PP) · הגבלה: להסיר לחלוטין את רדיד האלומיניום', '0.42 $ לק״ג', 'אקופונטו פיניירוס (0.6 ק״מ) · קואופרטיב וילה מריאנה (2.1 ק״מ)', now() - interval '5 days'),
  ('dd000000-0000-4000-8000-000000000040', 'cc000000-0000-4000-8000-000000000008', 'kk', 'Сүт өнімдеріне арналған термоформаланған ыдыс (PP #5, 170 г)', '1. Йогурт немесе май қалдықтарын жуып тазалаңыз. 2. Жиегіндегі фольга қақпақшасын толық сыпырып алыңыз. 3. Құрғақ ыдысты пластик контейнеріне салыңыз.', 'Изотактикалық полипропилен гомополимері (ПП #5)', 'Үдеріс: Қайталама полипропиленді ұсақтау және құю · Стандарт: Шайыр коды #5 (PP) · Шектеу: Алюминий фольга қақпағын бөліп алу', '0,42 $ / кг', 'Пиньейрус экобекеті (0,6 км) · Вила-Мариана кооперативі (2,1 км)', now() - interval '5 days'),
  ('dd000000-0000-4000-8000-000000000041', 'cc000000-0000-4000-8000-000000000009', 'pt', 'Cabo USB blindado de dados e energia (1,5 m)', '1. Enrole o cabo e prenda-o para não enroscar nas esteiras de triagem. 2. Deposite em um coletor exclusivo de eletrônicos para granulação do cobre.', 'Condutores de cobre estanhado multifilar com capa isolante de TPE/PVC', 'Processo: Trituração mecânica e separação densimétrica do cobre · Norma: ABNT NBR 16156 (REEE Categoria 6) · Restrição: Nunca queimar a capa plástica', 'R$ 11,20 / kg de cobre contido', 'Ponto Verde Paulista (1,8 km) · Ecoponto Pinheiros (1,1 km)', now() - interval '4 days'),
  ('dd000000-0000-4000-8000-000000000042', 'cc000000-0000-4000-8000-000000000009', 'es', 'Cable USB blindado de datos y carga (1,5 m)', '1. Enrolle el cable y sujételo para evitar enredos en la planta clasificadora. 2. Deposítelo en un punto de residuos electrónicos para recuperar el cobre.', 'Conductores de cobre estañado trenzado con cubierta aislante TPE/PVC', 'Proceso: Granulación mecánica y mesa densimétrica de cobre · Norma: RAEE Categoría 6 · Restricción: No quemar el aislamiento ni tirar en plásticos', 'US$ 2,10 / kg contenido de cobre', 'Ponto Verde Paulista (1,8 km) · Ecoponto Pinheiros (1,1 km)', now() - interval '4 days'),
  ('dd000000-0000-4000-8000-000000000043', 'cc000000-0000-4000-8000-000000000009', 'ru', 'Экранированный USB-кабель питания и данных (1,5 м)', '1. Сверните кабель кольцом, чтобы он не наматывался на валы сортировки. 2. Сдайте в контейнер для электронных отходов на грануляцию меди.', 'Многожильные луженые медные проводники в изоляции ТПЭ/ПВХ', 'Процесс: Механическое шредирование и пневмосепарация меди · Стандарт: WEEE Категория 6 · Ограничение: Не обжигать изоляцию', '2,10 $ / кг медной жилы', 'Понту-Верди Паулиста (1,8 км) · Экопункт Пиньейрус (1,1 км)', now() - interval '4 days'),
  ('dd000000-0000-4000-8000-000000000044', 'cc000000-0000-4000-8000-000000000009', 'he', 'כבל USB מסוכך לנתונים וטעינה (1.5 מ׳)', '1. גלגלו את הכבל ואבטחו אותו כדי שלא יסתבך במסועי המיון. 2. השליכו למכל ייעודי לפסולת אלקטרונית להפרדת הנחושת.', 'מוליכי נחושת מצופת בדיל בבידוד TPE/PVC', 'תהליך: גריסת כבלים מכנית והפרדת נחושת בשולחן אוויר · תקן: WEEE קטגוריה 6 · הגבלה: אין לשרוף את הבידוד', '2.10 $ לק״ג תכולת נחושת', 'פונטו ורדה פאוליסטה (1.8 ק״מ) · אקופונטו פיניירוס (1.1 ק״מ)', now() - interval '4 days'),
  ('dd000000-0000-4000-8000-000000000045', 'cc000000-0000-4000-8000-000000000009', 'kk', 'Экрандалған деректер мен қуат USB кабелі (1,5 м)', '1. Сұрыптау біліктеріне оралмауы үшін кабельді сақина етіп жинаңыз. 2. Мысты бөліп алу үшін электронды қалдықтар контейнеріне тапсырыңыз.', 'ТЭП/ПВХ оқшаулағышы бар қалайыланған көп талшықты мыс өткізгіштер', 'Үдеріс: Кабельді механикалық ұсақтау және мысты ауа үстелінде бөлу · Стандарт: WEEE 6 санаты · Шектеу: Оқшаулағышты өртемеу', '2,10 $ / кг мыс құрамы', 'Понту-Верди Паулиста (1,8 км) · Пиньейрус экобекеті (1,1 км)', now() - interval '4 days'),
  ('dd000000-0000-4000-8000-000000000046', 'cc000000-0000-4000-8000-000000000010', 'pt', 'Lata de conserva e cesto de folha de flandres (FE #40)', '1. Remova restos de alimento e enxágue o interior. 2. Dobre a tampa serrilhada para dentro da lata por segurança. 3. Deposite no coletor de metais para separação magnética.', 'Aço de baixo carbono revestido com estanho eletrolítico (FE #40)', 'Processo: Separação por tambor magnético e aciaria elétrica · Norma: CEN #40 FE · Restrição: Esvaziar totalmente; não perfurar aerossóis', 'R$ 1,65 / kg de aço magnético', 'Cooperativa Vila Mariana (1,4 km) · Ecoponto Pinheiros (1,9 km)', now() - interval '3 days'),
  ('dd000000-0000-4000-8000-000000000047', 'cc000000-0000-4000-8000-000000000010', 'es', 'Bote de conserva y cesto de hojalata de acero (FE #40)', '1. Retire restos de comida y enjuague el interior. 2. Pliegue el borde cortante de la tapa hacia adentro. 3. Deposítelo en el contenedor de metales para separación magnética.', 'Acero de bajo carbono recubierto de estaño electrolítico (FE #40)', 'Proceso: Separación por tambor magnético y acería de arco eléctrico · Norma: CEN #40 FE · Restricción: Vaciar por completo', 'US$ 0,31 / kg acero magnético', 'Cooperativa Vila Mariana (1,4 km) · Ecoponto Pinheiros (1,9 km)', now() - interval '3 days'),
  ('dd000000-0000-4000-8000-000000000048', 'cc000000-0000-4000-8000-000000000010', 'ru', 'Жестяная консервная банка и стальное ведерко (FE #40)', '1. Очистите и ополосните от остатков пищи. 2. Загните острый край крышки внутрь банки. 3. Поместите в контейнер для металла на магнитную сепарацию.', 'Низкоуглеродистая сталь с электролитическим лужением (FE #40)', 'Процесс: Магнитная сепарация и электродуговая плавка стали · Стандарт: CEN #40 FE · Ограничение: Полностью опорожнить тару', '0,31 $ / кг магнитной стали', 'Кооператив Вила-Мариана (1,4 км) · Экопункт Пиньейрус (1,9 км)', now() - interval '3 days'),
  ('dd000000-0000-4000-8000-000000000049', 'cc000000-0000-4000-8000-000000000010', 'he', 'קופסת שימורים ופח מפלדה מצופת בדיל (FE #40)', '1. נקו ושטפו שאריות מזון מהפחית. 2. כופפו פנימה שוליים חדים של המכסה לבטיחות. 3. השליכו למכל המתכות להפרדה מגנטית.', 'פלדה דלת-פחמן בציפוי בדיל אלקטרוליטי (FE #40)', 'תהליך: הפרדת תוף מגנטי והתכה בתנור קשת חשמלית · תקן: CEN #40 FE · הגבלה: לרוקן לחלוטין שאריות מזון', '0.31 $ לק״ג פלדה מגנטית', 'קואופרטיב וילה מריאנה (1.4 ק״מ) · אקופונטו פיניירוס (1.9 ק״מ)', now() - interval '3 days'),
  ('dd000000-0000-4000-8000-000000000050', 'cc000000-0000-4000-8000-000000000010', 'kk', 'Қаңылтыр консерві қалбыры мен болат шелек (FE #40)', '1. Тамақ қалдықтарынан тазартып, шайып жіберіңіз. 2. Қақпақтың өткір жиегін ішке қарай майыстырыңыз. 3. Магниттік бөлу үшін металл контейнеріне салыңыз.', 'Электролиттік қалайы жалатылған төмен көміртекті болат (FE #40)', 'Үдеріс: Магниттік барабанмен бөлу және электр доғалы болат балқыту · Стандарт: CEN #40 FE · Шектеу: Ішін толық босату', '0,31 $ / кг магнитті болат', 'Вила-Мариана кооперативі (1,4 км) · Пиньейрус экобекеті (1,9 км)', now() - interval '3 days'),
  ('dd000000-0000-4000-8000-000000000051', 'cc000000-0000-4000-8000-000000000011', 'pt', 'Invólucro metalizado de chocolate e guardanapo usado', '1. Separe eventual caixa externa de papelão limpo. 2. Feche o guardanapo engordurado e o filme laminado em saco de rejeito para coleta municipal.', 'Papel tissue de fibra curta saturado de gordura e filme BOPP metalizado', 'Processo: Destinação em aterro sanitário controlado · Norma: Multicamada e fibra engordurada não repolpável · Restrição: Não colocar no cesto de papel nem na composteira', 'Sem valor de revenda de sucata', 'Coleta Domiciliar Municipal', now() - interval '2 days'),
  ('dd000000-0000-4000-8000-000000000052', 'cc000000-0000-4000-8000-000000000011', 'es', 'Envoltorio metalizado de chocolate y servilleta usada', '1. Separe primero cualquier caja exterior de cartón limpio. 2. Cierre la servilleta engrasada y el envoltorio laminado en una bolsa para la recogida municipal.', 'Papel tisú de fibra corta saturado de grasa y película BOPP metalizada', 'Proceso: Disposición en relleno sanitario controlado · Norma: Multicapa y fibra engrasada no repulpable · Restricción: No mezclar con papel seco ni compost', 'Sin valor de recuperación', 'Recolección Domiciliaria Municipal', now() - interval '2 days'),
  ('dd000000-0000-4000-8000-000000000053', 'cc000000-0000-4000-8000-000000000011', 'ru', 'Металлизированная обертка от шоколада и использованная салфетка', '1. Отделите чистую внешнюю картонную упаковку, если она есть. 2. Завяжите промасленную салфетку и композитную обертку в пакет для вывоза коммунальной службой.', 'Пропитанная жиром коротковолокнистая салфетка и металлизированная БОПП-пленка', 'Процесс: Захоронение на санитарном полигоне · Стандарт: Неперерабатываемый композит и загрязненное волокно · Ограничение: Не бросать в макулатуру и компост', 'Не имеет заготовительной стоимости', 'Муниципальный вывоз ТКО', now() - interval '2 days'),
  ('dd000000-0000-4000-8000-000000000054', 'cc000000-0000-4000-8000-000000000011', 'he', 'עטיפת שוקולד מתכתית ומפית נייר משומשת', '1. הפרידו תחילה כל אריזת קרטון חיצונית נקייה. 2. סגרו את המפית הספוגה בשומן ואת העטיפה הרבודה בשקית אשפה לאיסוף העירוני.', 'נייר טישו קצר-סיבים ספוג שומן ויריעת BOPP מתכתית', 'תהליך: הטמנה מבוקרת באתר פסולת מוסדר · תקן: יריעה רב-שכבתית וסיב משומן שאינו ניתן להפיכה לעיסה · הגבלה: להרחיק מפחי נייר וקומפוסט', 'ללא ערך גריטה', 'איסוף אשפה עירוני', now() - interval '2 days'),
  ('dd000000-0000-4000-8000-000000000055', 'cc000000-0000-4000-8000-000000000011', 'kk', 'Шоколадтың металдандырылған орамасы мен пайдаланылған майлық', '1. Таза сыртқы картон қорапшасын бөлек алыңыз. 2. Май сіңген майлық пен көпқабатты ораманы коммуналдық қоқыс пакетіне салып байлаңыз.', 'Май сіңген қысқа талшықты майлық және металдандырылған БОПП үлдірі', 'Үдеріс: Санитарлық полигонға көму · Стандарт: Қайта өңделмейтін композит пен майлы талшық · Шектеу: Макулатура мен компостқа қоспау', 'Қайталама шикізат құны жоқ', 'Муниципалдық тұрмыстық қалдық жинау', now() - interval '2 days'),
  ('dd000000-0000-4000-8000-000000000056', 'cc000000-0000-4000-8000-000000000012', 'pt', 'Folhas secas de jardim e restos de batata cozida', '1. Retire potes plásticos, talheres ou vidros antes de destinar. 2. Misture as folhas secas aos restos de batata para equilibrar carbono, nitrogênio e umidade. 3. Deposite na composteira doméstica ou no pátio comunitário.', 'Folhagem seca rica em carbono e tubérculos amiláceos (C:N ~25:1)', 'Processo: Compostagem aeróbica em leira ou minhocário · Ciclo: 60 a 90 dias · Restrição: Sem embalagens plásticas, vidros ou molhos gordurosos', 'Rende ~0,6 kg de húmus / kg', 'Horta Comunitária Butantã (0,4 km) · Pátio de Compostagem Pinheiros (1,7 km)', now() - interval '1 day'),
  ('dd000000-0000-4000-8000-000000000057', 'cc000000-0000-4000-8000-000000000012', 'es', 'Hojas secas de jardín y restos de papa cocida', '1. Retire envases plásticos, cubiertos o frascos de vidrio. 2. Mezcle las hojas secas con los restos de papa para equilibrar carbono y humedad. 3. Deposítelo en la compostera doméstica o comunitaria.', 'Follaje seco rico en carbono y tubérculos feculentos (C:N ~25:1)', 'Proceso: Compostaje aeróbico en pila o lombricompostera · Ciclo: 60 a 90 días · Restricción: Sin envases plásticos, vidrios ni aderezos grasos', 'Rinde ~0,6 kg de humus / kg', 'Huerta Comunitaria Butantã (0,4 km) · Patio de Compostaje Pinheiros (1,7 km)', now() - interval '1 day'),
  ('dd000000-0000-4000-8000-000000000058', 'cc000000-0000-4000-8000-000000000012', 'ru', 'Сухие садовые листья и остатки отварного картофеля', '1. Уберите пластиковые контейнеры, приборы и стеклянные банки. 2. Перемешайте сухие листья с картофельными остатками для баланса углерода и влажности. 3. Поместите в домашний или районный компостер.', 'Богатая углеродом сухая листва и крахмалистые клубни (C:N ~25:1)', 'Процесс: Аэробное компостирование в буртах или вермикомпостер · Цикл: 60–90 дней · Ограничение: Без пластиковой тары, стекла и жирных соусов', 'Выход ~0,6 кг гумуса на 1 кг', 'Общественный сад Бутантан (0,4 км) · Площадка компостирования Пиньейрус (1,7 км)', now() - interval '1 day'),
  ('dd000000-0000-4000-8000-000000000059', 'cc000000-0000-4000-8000-000000000012', 'he', 'עלים יבשים מהגינה ושאריות תפוחי אדמה מבושלים', '1. הפרידו תחילה קופסאות פלסטיק, סכו״ם או צנצנות זכוכית. 2. ערבבו את העלים היבשים עם שאריות תפוחי האדמה לאיזון פחמן ולחות. 3. העבירו לקומפוסטר ביתי או לחצר קומפוסט שכונתית.', 'עלווה יבשה עשירה בפחמן ופקעות עמילניות (יחס פחמן-חנקן ~25:1)', 'תהליך: קומפוסט אירובי בערימה או קומפוסט תולעים · מחזור: 60–90 יום · הגבלה: ללא אריזות פלסטיק, זכוכית או רטבים שומניים', 'מפיק ~0.6 ק״ג הומוס לק״ג', 'גינה קהילתית בוטנטן (0.4 ק״מ) · חצר קומפוסט פיניירוס (1.7 ק״מ)', now() - interval '1 day'),
  ('dd000000-0000-4000-8000-000000000060', 'cc000000-0000-4000-8000-000000000012', 'kk', 'Құрғақ бақша жапырақтары мен пісірілген картоп қалдықтары', '1. Пластик ыдыстарды, ас құралдарын немесе шыны банкаларды бөлек алыңыз. 2. Көміртек пен ылғал теңгерімі үшін құрғақ жапырақтарды картоп қалдықтарымен араластырыңыз. 3. Үй немесе қоғамдық компостерге салыңыз.', 'Көміртекке бай құрғақ жапырақтар мен крахмалды түйнектер (C:N ~25:1)', 'Үдеріс: Аэробты компосттау немесе вермикомпостер · Цикл: 60–90 күн · Шектеу: Пластик қаптамасыз, шынысыз және майлы тұздықтарсыз', '1 кг-нан ~0,6 кг гумус алынады', 'Бутантан қоғамдық бағы (0,4 км) · Пиньейрус компост алаңы (1,7 км)', now() - interval '1 day')
ON CONFLICT DO NOTHING;

